add(2025,27,'spectro','Köre göre sıfırlanmış sistemde C=10×(0,250/0,500)=5 g/dL. Hasta absorbansı standardın yarısı olduğundan derişim de yarısıdır.','10 g/dL standart derişimidir; hasta absorbansı standardın yarısıdır. | 20 g/dL oranı ters kullanmakla elde edilir. | 8 g/dL verilen 1/2 absorbans oranını sağlamaz. | 10×1/2=5 g/dL doğru sonuçtur. | 2,5 g/dL standardın dörtte biridir; absorbans ise yarısıdır.')
add(2025,29,'lipid','Dihidroksiaseton üç karbon ve keton grubu taşıyan ketotriozdur. Gliseraldehit üç karbonlu fakat aldehit taşıyan aldotriozdur.','Glukozamin aminoşekerdir; ketotrioz değildir. | Ksilüloz beş karbonlu ketopentozdur. | Dihidroksiaseton üç karbonlu ketozdur. | Fruktoz altı karbonlu ketoheksozdur. | Gliseraldehit aldotriozdur; ketotrioz değildir.')
add(2025,31,'lipid','İzomaltoz iki glukozu α(1→6) bağıyla birleştirir. Maltoz α(1→4), sellobiyoz β(1→4) bağlı iki glukoz içerir.','Sükroz glukoz ve fruktozu iki anomerik karbon üzerinden bağlar. | Laktoz galaktoz ve glukozu β(1→4) bağlar. | İzomaltoz α(1→4) değil α(1→6) bağı taşır. | Maltoz için α(1→4) bağlantısı doğrudur. | Sellobiyoz için β(1→4) bağlantısı doğrudur.')
add(2025,33,'energy','Enzime sıkı bağlanan yardımcı grup prostetik grup; protein kısmı apoenzim, etkin tam yapı holoenzimdir. “Haloenzim” sıkı bağlı kofaktörün adı değildir.','Birçok metabolik düzenleyici enzim allosterik denetim gösterir. | Serin, treonin ve tirozin fosforilasyonu yaygın kovalent düzenlemedir. | İndüklenmiş uyumda bağlanma aktif bölgenin konformasyonunu değiştirebilir. | Yüksek substrat kompetitif inhibisyonun etkisini azaltabilir; inhibitörün bağlanma sabiti değişmek zorunda değildir. | Sıkı bağlı kofaktör prostetik gruptur; holoenzim apoenzim ile kofaktörün birlikte oluşturduğu yapıdır.')
clone(2025,35,2024,57)
add(2025,36,'vit','Kobalamin mide kaynaklı intrinsik faktöre bağlanıp terminal ileumda reseptör aracılı emilir. Diğer vitaminler aynı intrinsik faktör yoluna ihtiyaç duymaz.','Kobalamin/B12 intrinsik faktörle terminal ileumdan emilir. | Biyotin emilimi intrinsik faktöre bağlı değildir. | Folat emilimi B12’nin intrinsik faktör yolunu kullanmaz. | Niasin intrinsik faktöre gereksinmez. | Tiamin emilimi intrinsik faktöre bağlı değildir.')
add(2025,37,'vit','Folat nükleotid sentezine tek karbonlu birimler sağlar. Eksikliğinde DNA sentezi aksayıp megaloblastik anemi gelişebilir; B12 eksikliği de benzer anemi yapabilir fakat seçeneklerde yoktur.','Folik asit eksikliği DNA sentezini bozarak megaloblastik anemiye yol açabilir. | C vitamini eksikliği skorbütle ilişkilidir. | Pantotenat eksikliği bu klasik megaloblastik anemi eşleşmesi değildir. | Niasin eksikliği pellagrayla ilişkilidir. | Retinoik asit A vitamini türevidir; sorudaki DNA sentezi kofaktörü değildir.')
add(2025,38,'vit','Transaminazlar piridoksal fosfat, yani aktif B6 vitamini kullanır. Eritrosit transaminazının PLP ile uyarılması B6 durumunu değerlendirmede kullanılabilir.','Tiamin transketolaz gibi enzimlerle ilişkilidir. | Piridoksal fosfat transaminazların gerekli koenzimidir. | Kobalamin transaminazın PLP koenzimi değildir. | Pantotenat CoA ve ACP’ye katılır. | Niasin NAD/NADP’nin öncülüdür.')
add(2025,39,'vit','Menakinon-7 K2 vitamininin bir biçimidir. K vitamini bağımlı γ-karboksilasyon, pıhtılaşma proteinlerinde Ca²⁺ bağlayan glutamat türevlerini oluşturur.','Retinol A vitaminidir; γ-karboksilaz kofaktörü değildir. | Alfa tokoferol E vitaminidir; başlıca antioksidandır. | Menakinon-7 K vitamini biçimidir ve γ-karboksilasyonla ilişkilidir. | Kalsitriol aktif D vitaminidir; pıhtılaşma proteini karboksilaz kofaktörü değildir. | Askorbik asit kollajen hidroksilasyonu gibi süreçlerde görev yapar; bu γ-karboksilasyonun kofaktörü değildir.')
add(2025,40,'vit','Aşırı preform A vitamini/retinol alımı embriyonik gelişimi bozabilir. Soruda belirtilen klasik teratojenite ilişkisi retinole aittir; bu bilgi doz önerisi değildir.','Retinolün aşırı alımı gelişmekte olan fetüste doğumsal kusur riskiyle ilişkilidir. | Aktif D vitamini aşırılığı toksik olabilir; sorudaki klasik retinoid teratojenite eşleşmesi değildir. | E vitamini bu listedeki klasik retinoid gelişim bozukluğu nedenini karşılamaz. | K2 biçimi retinolün embriyonik gen düzenlenmesi etkisini tanımlamaz. | PLP B6 biçimidir; hedeflenen preform A vitamini değildir.')
add(2025,42,'lipid',DATA[2021,58]['summary'],'PAF sn-1 konumunda eter bağlı alkil zincir taşır. | Sefalin tipik gliserofosfolipid sınıflamasıyla ilişkilidir; hedef PAF’tır. | Kardiyolipin difosfatidilgliseroldür; klasik PAF eter yapısı değildir. | Lesitin fosfatidilkolindir; tipik ester bağlı formu hedef değildir. | Sfingomiyelin gliserol değil sfingozin omurgası taşır; eter gliserofosfolipid değildir.')
add(2025,43,'lipid','DHAP, gliserol-3-fosfat dehidrogenazla NADH kullanılarak indirgenir. Gliserol kinaz ise serbest gliserolü ATP ile fosforiller; iki farklı yol karıştırılmamalıdır.','TAG sentezinde gliserol-3-fosfat ve aktif yağ açil-KoA kullanılır. | DHAP’tan dönüşüm kinaz/ATP ile değil dehidrogenaz/NADH ile gerçekleşir. | Açil-KoA sentetaz yağ asidini ATP→AMP+PPi enerjisiyle aktive eder. | İki açillenme fosfatidat oluşturur. | Fosfatidatın fosfatı çıkarılır; üçüncü açil eklenmesi TAG verir.')
add(2025,44,'lipid','Linoleik asitte metil ucuna en yakın çift bağ Δ12’dir. 18−12=6 olduğundan omega-6’dır ve insan için esansiyel yağ asididir.','Omega-6 sınıfı doğru olsa da nonesansiyel değildir. | Omega-3 değil omega-6’dır. | Hem omega sınıfı hem esansiyellik yanlıştır. | Linoleik asit esansiyel omega-6 yağ asididir. | Omega-9 değil omega-6’dır.')
